    coalesce((coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = "notes"."project_id")), false),
    coalesce((SELECT authz_int.scope_cmd('app.notes', 'update')), false),
    coalesce(true, false),
    coalesce((coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = "notes"."project_id")), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[4]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "notes";
END;

