-- app.notes insert (line 51): project.edit and author
CREATE POLICY "authz_insert" ON "app"."notes" FOR INSERT TO conf_app
  WITH CHECK (((SELECT authz_int.scope_cmd('app.notes', 'insert')) AND (coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_int."project__edit" v WHERE v.id = "notes"."project_id")))
    OR authz_gen."app.notes:insert:refuse"(("notes".*)::"app"."notes"));
COMMENT ON POLICY "authz_insert" ON "app"."notes" IS 'rowstile';

-- app.notes update (line 52): edit
CREATE POLICY "authz_update" ON "app"."notes" FOR UPDATE TO conf_app
  USING (((SELECT authz_int.scope_cmd('app.notes', 'update')) AND (coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = "notes"."project_id"))))
  WITH CHECK (((SELECT authz_int.scope_cmd('app.notes', 'update')) AND (coalesce("notes"."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = "notes"."project_id")))
    OR authz_gen."app.notes:update:refuse"(("notes".*)::"app"."notes"));
COMMENT ON POLICY "authz_update" ON "app"."notes" IS 'rowstile';

